        remarks,
        driver_name,
        slip_out_time,
        online_entry,
        offline_entry
      ];

      const result = await pool.query(query, values);

      if (result.rows.length === 0) {
        return res.status(404).json({ error: 'Purchase record not found' });
      }

      // Also update the details table
      const {
        vehicle_no = null,
        vendor_name = null,
        po_no = null,
        igp_no = null,
        item_code = null,
        item_desc = null,
        po_qty = null,
        igp_qty = null,
        balance_qty = null,
        igp_date = null,
        weight_per_bags = null,
        no_of_bags = null,
        bardana_type = null
      } = updateData;

      // Check if details record exists, then update or insert accordingly
      const checkQuery = `SELECT wb_item_p_id FROM wb_weighbridge_items_purchase WHERE wb_id = $1`;
      const checkResult = await pool.query(checkQuery, [wbId]);

      if (checkResult.rows.length > 0) {
        // Update existing record
        const detailsQuery = `
          UPDATE wb_weighbridge_items_purchase 
          SET 
            vehicle_no = $2,
            vendor_name = $3,
            po_no = $4,
            igp_no = $5,
