          no_of_bags ? parseInt(no_of_bags) : null,
          bardana_type
        ];

        await pool.query(insertQuery, insertValues);
      }

      console.log(`Updated purchase record: WB_ID ${wbId}`);
      res.json(result.rows[0]);
