          item.bags,
          item.pb,
          item.percentage,
          typeof item.weight === 'string' ? parseFloat(item.weight) || 0 : item.weight,
          item.total || (item.bags * item.pb)
        ];

        console.log('Inserting deduction record:', values);
        await pool.query(query, values);
