import { cameras, streamSessions, streamStats, type Camera, type InsertCamera, type StreamSession, type InsertStreamSession, type StreamStats, type InsertStreamStats } from "@shared/schema";

export interface IStorage {
  // Camera operations
  getCamera(id: number): Promise<Camera | undefined>;
  getCameraByIp(ip: string): Promise<Camera | undefined>;
  createCamera(camera: InsertCamera): Promise<Camera>;
  updateCamera(id: number, updates: Partial<InsertCamera>): Promise<Camera | undefined>;

  // Stream session operations
  createStreamSession(session: InsertStreamSession): Promise<StreamSession>;
  getActiveStreamSession(cameraId: number): Promise<StreamSession | undefined>;
  endStreamSession(sessionId: string): Promise<void>;

  // Stream stats operations
  addStreamStats(stats: InsertStreamStats): Promise<StreamStats>;
  getLatestStreamStats(cameraId: number): Promise<StreamStats | undefined>;
}

export class MemStorage implements IStorage {
  private cameras: Map<number, Camera>;
  private streamSessions: Map<number, StreamSession>;
  private streamStats: Map<number, StreamStats>;
  private currentCameraId: number;
  private currentSessionId: number;
  private currentStatsId: number;

  constructor() {
    this.cameras = new Map();
    this.streamSessions = new Map();
    this.streamStats = new Map();
    this.currentCameraId = 1;
    this.currentSessionId = 1;
    this.currentStatsId = 1;

    // Initialize with the default camera from the requirements - do it synchronously
    const id = this.currentCameraId++;
    const camera: Camera = {
      id,
      name: "Camera 01",
      ip: "192.168.6.108",
      port: 554,
      username: "admin",
      password: "Abc@12345",
      rtspUrl: "rtsp://admin:Abc@12345@192.168.6.108:554/cam/realmonitor?channel=1&subtype=0",
      isActive: true,
      createdAt: new Date(),
    };
    this.cameras.set(id, camera);
    console.log("Initialized camera with ID:", id, "Total cameras:", this.cameras.size);
  }

  async getCamera(id: number): Promise<Camera | undefined> {
    return this.cameras.get(id);
  }

  async getCameraByIp(ip: string): Promise<Camera | undefined> {
    return Array.from(this.cameras.values()).find(camera => camera.ip === ip);
  }

  async createCamera(insertCamera: InsertCamera): Promise<Camera> {
    const id = this.currentCameraId++;
    const camera: Camera = {
      id,
      name: insertCamera.name,
      ip: insertCamera.ip,
      port: insertCamera.port,
      username: insertCamera.username,
      password: insertCamera.password,
      rtspUrl: insertCamera.rtspUrl,
      isActive: insertCamera.isActive ?? true,
      createdAt: new Date(),
    };
    this.cameras.set(id, camera);
    return camera;
  }

  async updateCamera(id: number, updates: Partial<InsertCamera>): Promise<Camera | undefined> {
    const camera = this.cameras.get(id);
    if (!camera) return undefined;

    const updatedCamera = { ...camera, ...updates };
    this.cameras.set(id, updatedCamera);

    // Log the camera update for debugging
    console.log('Camera updated:', {
      id: updatedCamera.id,
      name: updatedCamera.name,
      ip: updatedCamera.ip,
      port: updatedCamera.port,
      rtspUrl: updatedCamera.rtspUrl
    });

    return updatedCamera;
  }

  async createStreamSession(insertSession: InsertStreamSession): Promise<StreamSession> {
    const id = this.currentSessionId++;
    const session: StreamSession = {
      id,
      cameraId: insertSession.cameraId ?? null,
      sessionId: insertSession.sessionId,
      isActive: insertSession.isActive ?? true,
      startedAt: new Date(),
      endedAt: null,
    };
    this.streamSessions.set(id, session);
    return session;
  }

  async getActiveStreamSession(cameraId: number): Promise<StreamSession | undefined> {
    return Array.from(this.streamSessions.values()).find(
      session => session.cameraId === cameraId && session.isActive
    );
  }

  async endStreamSession(sessionId: string): Promise<void> {
    const session = Array.from(this.streamSessions.values()).find(
      s => s.sessionId === sessionId
    );
    if (session) {
      session.isActive = false;
      session.endedAt = new Date();
      this.streamSessions.set(session.id, session);
    }
  }

  async addStreamStats(insertStats: InsertStreamStats): Promise<StreamStats> {
    const id = this.currentStatsId++;
    const stats: StreamStats = {
      id,
      cameraId: insertStats.cameraId ?? null,
      bandwidth: insertStats.bandwidth || null,
      fps: insertStats.fps || null,
      latency: insertStats.latency || null,
      droppedFrames: insertStats.droppedFrames || 0,
      timestamp: new Date(),
    };
    this.streamStats.set(id, stats);
    return stats;
  }

  async getLatestStreamStats(cameraId: number): Promise<StreamStats | undefined> {
    const cameraStats = Array.from(this.streamStats.values())
      .filter(stats => stats.cameraId === cameraId)
      .sort((a, b) => (b.timestamp?.getTime() || 0) - (a.timestamp?.getTime() || 0));

    return cameraStats[0];
  }
}

export const storage = new MemStorage();

server/stream-service.ts.content:
import { WebSocketServer, WebSocket } from 'ws';
import { Server } from 'http';
import { storage } from './storage';
import { nanoid } from 'nanoid';

export interface StreamConnection {
  id: string;
  cameraId: number;
  ws: WebSocket;
  startTime: Date;
  isActive: boolean;
}

export class StreamService {
  private wss: WebSocketServer | null = null;
  private connections: Map<string, StreamConnection> = new Map();
  private streamIntervals: Map<string, NodeJS.Timeout> = new Map();

  initialize(server: Server): void {
    this.wss = new WebSocketServer({ server, path: '/ws/stream' });

    this.wss.on('connection', (ws: WebSocket) => {
      const connectionId = nanoid();

      ws.on('message', async (message: string) => {
        try {
          const data = JSON.parse(message.toString());
          await this.handleMessage(connectionId, ws, data);
        } catch (error) {
          console.error('Error handling WebSocket message:', error);
          ws.send(JSON.stringify({ type: 'error', message: 'Invalid message format' }));
        }
      });

      ws.on('close', () => {
        this.handleDisconnection(connectionId);
      });

      ws.on('error', (error) => {
        console.error('WebSocket error:', error);
        this.handleDisconnection(connectionId);
      });

      // Send connection acknowledgment
      ws.send(JSON.stringify({ type: 'connected', connectionId }));
    });
  }

  private async handleMessage(connectionId: string, ws: WebSocket, message: any): Promise<void> {
    switch (message.type) {
      case 'start_stream':
        await this.startStream(connectionId, ws, message.cameraId);
        break;
      case 'stop_stream':
        await this.stopStream(connectionId);
        break;
      case 'get_camera_info':
        await this.sendCameraInfo(ws, message.cameraId);
        break;
      default:
        ws.send(JSON.stringify({ type: 'error', message: 'Unknown message type' }));
    }
  }

  private async startStream(connectionId: string, ws: WebSocket, cameraId: number): Promise<void> {
    try {
      const camera = await storage.getCamera(cameraId);
      if (!camera) {
        ws.send(JSON.stringify({ type: 'error', message: 'Camera not found' }));
        return;
      }

      // Create stream session
      const session = await storage.createStreamSession({
        cameraId,
        sessionId: nanoid(),
        isActive: true,
      });

      // Create connection record
      const connection: StreamConnection = {
        id: connectionId,
        cameraId,
        ws,
        startTime: new Date(),
        isActive: true,
      };

      this.connections.set(connectionId, connection);

      // Send stream started confirmation
      ws.send(JSON.stringify({
        type: 'stream_started',
        cameraId,
        sessionId: session.sessionId,
        camera: {
          name: camera.name,
          ip: camera.ip,
          port: camera.port,
          rtspUrl: camera.rtspUrl,
        },
      }));

      // Start sending stream stats
      this.startStreamStatsInterval(connectionId, cameraId);

      // Simulate stream connection process
      setTimeout(() => {
        if (this.connections.has(connectionId)) {
          ws.send(JSON.stringify({
            type: 'stream_connected',
            status: 'connected',
          }));
        }
      }, 2000);

    } catch (error) {
      console.error('Error starting stream:', error);
      ws.send(JSON.stringify({ type: 'error', message: 'Failed to start stream' }));
    }
  }

  private async stopStream(connectionId: string): Promise<void> {
    const connection = this.connections.get(connectionId);
    if (!connection) return;

    // Stop stats interval
    const interval = this.streamIntervals.get(connectionId);
    if (interval) {
      clearInterval(interval);
      this.streamIntervals.delete(connectionId);
    }

    // End stream session
    const activeSession = await storage.getActiveStreamSession(connection.cameraId);
    if (activeSession) {
      await storage.endStreamSession(activeSession.sessionId);
    }

    // Mark connection as inactive
    connection.isActive = false;
    this.connections.delete(connectionId);

    // Send stop confirmation
    connection.ws.send(JSON.stringify({ type: 'stream_stopped' }));
  }

  private handleDisconnection(connectionId: string): void {
    this.stopStream(connectionId);
  }

  private startStreamStatsInterval(connectionId: string, cameraId: number): void {
    const interval = setInterval(async () => {
      const connection = this.connections.get(connectionId);
      if (!connection || !connection.isActive) {
        clearInterval(interval);
        this.streamIntervals.delete(connectionId);
        return;
      }

      // Generate realistic stream stats
      const stats = {
        cameraId,
        bandwidth: (1.0 + Math.random() * 0.5).toFixed(1) + ' Mbps',
        fps: 24 + Math.floor(Math.random() * 3),
        latency: 10 + Math.floor(Math.random() * 10),
        droppedFrames: Math.floor(Math.random() * 3),
      };

      // Store stats
      await storage.addStreamStats(stats);

      // Calculate uptime
      const uptime = Math.floor((Date.now() - connection.startTime.getTime()) / 1000);
      const hours = Math.floor(uptime / 3600).toString().padStart(2, '0');
      const minutes = Math.floor((uptime % 3600) / 60).toString().padStart(2, '0');
      const seconds = (uptime % 60).toString().padStart(2, '0');

      // Send stats to client
      connection.ws.send(JSON.stringify({
        type: 'stream_stats',
        stats: {
          ...stats,
          uptime: `${hours}:${minutes}:${seconds}`,
          buffer: '2.1s',
        },
      }));
    }, 1000);

    this.streamIntervals.set(connectionId, interval);
  }

  private async sendCameraInfo(ws: WebSocket, cameraId: number): Promise<void> {
    try {
      const camera = await storage.getCamera(cameraId);
      if (!camera) {
        ws.send(JSON.stringify({ type: 'error', message: 'Camera not found' }));
        return;
      }

      ws.send(JSON.stringify({
        type: 'camera_info',
        camera: {
          id: camera.id,
          name: camera.name,
          ip: camera.ip,
          port: camera.port,
          username: camera.username,
          rtspUrl: camera.rtspUrl,
          isActive: camera.isActive,
        },
      }));
    } catch (error) {
      console.error('Error getting camera info:', error);
      ws.send(JSON.stringify({ type: 'error', message: 'Failed to get camera info' }));
    }
  }
}

export const streamService = new StreamService();

