import { useAuth } from "@/lib/auth";
import { useLocation } from "wouter";
import { useEffect } from "react";

interface ProtectedRouteProps {
  children: React.ReactNode;
}

export default function ProtectedRoute({ children }: ProtectedRouteProps) {
  const { isAuthenticated, isLoading } = useAuth();
  const [, setLocation] = useLocation();

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      setLocation("/login");
    }
  }, [isAuthenticated, isLoading, setLocation]);

  if (isLoading) {
    return <div className="flex items-center justify-center min-h-screen">Loading...</div>;
  }

  if (!isAuthenticated) {
    return null;
  }

  return <>{children}</>;
}

client/src/components/sidebar.tsx.content:
import React, { useState, useEffect, useRef } from "react";
import { Link, useLocation } from "wouter";
import {
  Home,
  Settings,
  Video,
  Menu,
  X,
  Scale,
  FileText,
  LogOut,
  User,
  BarChart3,
  Upload,
  ShoppingCart,
  RotateCcw,
  Network,
  ChevronDown,
  ChevronRight,
  Users,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useAuth } from "@/lib/auth";

const getNavigation = (isAdmin: boolean) => {
  const baseNavigation = [
    { name: "Home", href: "/", icon: Home },
    {
      name: "Purchase Form",
      icon: FileText,
      hasSubItems: true,
      subItems: [
        {
          name: "Purchase Online",
          href: "/purchase-form?type=online",
          icon: FileText,
        },
        {
          name: "Purchase Offline",
          href: "/purchase-form?type=offline",
          icon: FileText,
        },
      ],
    },
    {
      name: "Sale Form",
      icon: ShoppingCart,
      hasSubItems: true,
      subItems: [
        {
          name: "Sales Online",
          href: "/sales-form?type=online",
          icon: ShoppingCart,
        },
        {
          name: "Sales Offline",
          href: "/sales-form?type=offline",
          icon: ShoppingCart,
        },
      ],
    },
    { name: "Voucher Entry", href: "/voucher-entry", icon: FileText },
    { name: "Voucher View", href: "/voucher-view", icon: FileText },
    {
      name: "Returns",
      icon: RotateCcw,
      hasSubItems: true,
      subItems: [
        {
          name: "Sale Return",
          href: "/sales-return",
          icon: RotateCcw,
        },
        {
          name: "Purchase Return",
          href: "/purchase-return?type=online",
          icon: RotateCcw,
        },
      ],
    },
    { name: "Sale Node", href: "/sale-node", icon: Network },
    { name: "Reports", href: "/reports", icon: BarChart3 },
    { name: "Camera Settings", href: "/settings", icon: Settings },
    {
      name: "Weighbridge Settings",
      href: "/weighbridge-settings",
      icon: Scale,
    },
  ];

  if (isAdmin) {
    baseNavigation.splice(-2, 0, {
      name: "Role",
      href: "/role-management",
      icon: Users,
    });
  }

  return baseNavigation;
};

export default function Sidebar() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [expandedItems, setExpandedItems] = useState<string[]>([]);
  const [, setLocation] = useLocation(); // unused now
  const { user, logout } = useAuth();
  const sidebarRef = useRef(null);

  const isActive = (href: string) => {
    try {
      const currentUrl = new URL(window.location.href);
      const targetUrl = new URL(href, window.location.origin);
      return (
        currentUrl.pathname === targetUrl.pathname &&
        currentUrl.search === targetUrl.search
      );
    } catch {
      return false;
    }
  };

  const isAdmin = user?.userName === "admin" || user?.userid === 1;
  const navigation = getNavigation(isAdmin);

  useEffect(() => {
    const storedExpandedItems = localStorage.getItem("expandedItems");
    if (storedExpandedItems) {
      try {
        const parsedItems = JSON.parse(storedExpandedItems);
        setExpandedItems(Array.isArray(parsedItems) ? parsedItems : []);
      } catch {
        setExpandedItems([]);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem("expandedItems", JSON.stringify(expandedItems));
  }, [expandedItems]);

  const toggleExpanded = (itemName: string) => {
    setExpandedItems((prev) => {
      const expandableItems = ["Purchase Form", "Sale Form"];
      if (prev.includes(itemName)) {
        return prev.filter((name) => name !== itemName);
      } else {
        const filteredItems = prev.filter(
          (name) => !expandableItems.includes(name),
        );
        return [...filteredItems, itemName];
      }
    });
  };

  const handleNavigation = (href: string) => {
    if (href !== window.location.pathname + window.location.search) {
      window.location.href = href; // 👈 Force reload
    }
    setIsMobileMenuOpen(false);
  };

  const handleLogout = async () => {
    await logout();
    setIsMobileMenuOpen(false);
  };

  return (
    <>
      {/* Mobile menu button */}
      <div className="lg:hidden fixed top-4 left-4 z-50">
        <Button
          variant="outline"
          size="sm"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          className="bg-monitoring-slate border-monitoring-gray text-white hover:bg-monitoring-gray"
        >
          {isMobileMenuOpen ? (
            <X className="h-4 w-4" />
          ) : (
            <Menu className="h-4 w-4" />
          )}
        </Button>
      </div>

      {/* Sidebar */}
      <div
        ref={sidebarRef}
        className={cn(
          "fixed inset-y-0 left-0 z-40 w-64 bg-monitoring-slate border-r border-monitoring-gray transform transition-transform duration-200 ease-in-out lg:translate-x-0",
          isMobileMenuOpen
            ? "translate-x-0"
            : "-translate-x-full lg:translate-x-0",
        )}
      >
        <div className="flex flex-col h-full">
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-monitoring-gray">
            <h1 className="text-xl font-bold text-white">Weighbridge System</h1>
          </div>

          {/* Navigation */}
          <nav className="flex-1 p-4 space-y-1">
            {navigation.map((item) => {
              if (item.hasSubItems) {
                const isExpanded = expandedItems.includes(item.name);
                const hasActiveSubItem = item.subItems?.some((subItem) =>
                  isActive(subItem.href),
                );

                return (
                  <div key={item.name} className="space-y-1">
                    <Button
                      variant="ghost"
                      className={cn(
                        "w-full justify-between text-left h-12 px-4",
                        hasActiveSubItem
                          ? "bg-blue-600 text-white hover:bg-blue-700"
                          : "text-gray-300 hover:bg-monitoring-gray hover:text-white",
                      )}
                      onClick={() => toggleExpanded(item.name)}
                    >
                      <div className="flex items-center">
                        <item.icon className="mr-3 h-5 w-5" />
                        {item.name}
                      </div>
                      {isExpanded ? (
                        <ChevronDown className="h-4 w-4" />
                      ) : (
                        <ChevronRight className="h-4 w-4" />
                      )}
                    </Button>

                    {isExpanded && (
                      <div className="ml-4 space-y-1">
                        {item.subItems?.map((subItem) => {
                          const isSubActive = isActive(subItem.href);

                          return (
                            <Button
                              key={subItem.name}
                              variant="ghost"
                              className={cn(
                                "w-full justify-start text-left h-10 px-4 ml-2",
                                isSubActive
                                  ? "bg-blue-600 text-white hover:bg-blue-700"
                                  : "text-gray-400 hover:bg-monitoring-gray/70 hover:text-white",
                              )}
                              onClick={() => handleNavigation(subItem.href)}
                            >
                              <subItem.icon className="mr-3 h-4 w-4" />
                              {subItem.name}
                            </Button>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              } else {
                const isItemActive = isActive(item.href ?? "");

                return (
                  <Button
                    key={item.name}
                    variant="ghost"
                    className={cn(
                      "w-full justify-start text-left h-12 px-4",
                      isItemActive
                        ? "bg-blue-600 text-white hover:bg-blue-700"
                        : "text-gray-300 hover:bg-monitoring-gray hover:text-white",
                    )}
                    onClick={() => handleNavigation(item.href ?? "")}
                  >
                    <item.icon className="mr-3 h-5 w-5" />
                    {item.name}
                  </Button>
                );
              }
            })}
          </nav>

          {/* User Info & Logout */}
          <div className="p-4 border-t border-monitoring-gray space-y-3">
            <div className="flex items-center space-x-3 px-2">
              <div className="flex items-center justify-center w-8 h-8 bg-monitoring-blue rounded-full">
                <User className="h-4 w-4 text-white" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-white truncate">
                  {user?.userName || "User"}
                </p>
                <p className="text-xs text-gray-400">Authenticated</p>
              </div>
            </div>
            <Button
              variant="ghost"
              onClick={handleLogout}
              className="w-full justify-start text-left h-10 px-2 text-gray-300 hover:bg-red-600 hover:text-white"
            >
              <LogOut className="mr-3 h-4 w-4" />
              Logout
            </Button>
            <div className="text-xs text-gray-400 text-center pt-2">
              Live Camera Monitoring System
            </div>
          </div>
        </div>
      </div>

      {/* Mobile menu overlay */}
      {isMobileMenuOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 z-30 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}
    </>
  );
}

client/src/components/stream-controls.ts.content:
import { Button } from "@/components/ui/button";
import { Play, Pause, RotateCcw, Maximize } from "lucide-react";

interface StreamControlsProps {
  isStreaming: boolean;
  onToggleStream: () => void;
  onReconnect: () => void;
}

export default function StreamControls({
  isStreaming,
  onToggleStream,
  onReconnect,
}: StreamControlsProps) {
  const handleFullscreen = () => {
    const element = document.getElementById('video-container');
    if (element) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        element.requestFullscreen();
      }
    }
  };

  return (
    <div className="flex items-center space-x-3">
      <Button
        onClick={onToggleStream}
        className="flex items-center space-x-2 bg-monitoring-blue hover:bg-blue-600 px-4 py-2"
      >
        {isStreaming ? (
          <Pause className="h-4 w-4" />
        ) : (
          <Play className="h-4 w-4" />
        )}
        <span className="text-sm font-medium">
          {isStreaming ? 'Pause' : 'Play'}
        </span>
      </Button>

      <Button
        onClick={onReconnect}
        variant="secondary"
        className="flex items-center space-x-2 bg-monitoring-gray hover:bg-gray-600 px-4 py-2"
      >
        <RotateCcw className="h-4 w-4" />
        <span className="text-sm font-medium">Reconnect</span>
      </Button>

      <Button
        onClick={handleFullscreen}
        variant="secondary"
        className="bg-monitoring-gray hover:bg-gray-600 px-3 py-2"
      >
        <Maximize className="h-4 w-4" />
      </Button>
    </div>
  );
}

