      const url = (selectedBranch && selectedBranch !== 'all') 
        ? `/api/purchases?branch_id=${selectedBranch}` 
        : '/api/purchases';
      const response = await fetch(url);
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || 'Failed to fetch purchase data');
      }
      return data;
    },
  });

