  // Fetch sales records
  const { data: salesData, refetch: refetchSales, error: salesError } = useQuery({
  queryKey: ['/api/sales', selectedBranch],
  queryFn: async () => {
    const url = (selectedBranch && selectedBranch !== 'all') 
      ? `/api/sales?branch_id=${selectedBranch}` 
      : '/api/sales';
